/**
 * A field that holds, formats and steps a number (`design/components/number-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/number-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/number-input'
import { normalizeProps } from '@zag-js/solid'

import {
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/number-input.module.css'

export interface NumberFormat {
  style?: 'decimal' | 'percent' | 'currency'
  currency?: string
  maximumFractionDigits?: number
}

export interface NumberInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | null
  disabled?: boolean
  /**
   * The chart tier's format descriptor, limited to what an editable field can parse back. It
   * formats the displayed text only. The committed value is always the raw number. Raw
   * `Intl.NumberFormatOptions` are not accepted.
   */
  format?: NumberFormat
  id?: string
  invalid?: boolean
  max?: number
  /**
   * Typed values are clamped at commit. The steppers snap to the step and stop at the limits.
   */
  min?: number
  /**
   * Posts the **plain number** on a hidden input, never the formatted text.
   */
  name?: string
  /**
   * Fires after the commit settles, so touched validation reads the committed number.
   */
  onBlur?: (event: FocusEvent) => void
  /**
   * Reports committed numbers only, never unparsed text and never `NaN`.
   */
  onChange?: (value: number | null) => void
  onFocus?: (event: FocusEvent) => void
  placeholder?: string
  /**
   * Affixes as defined in `input.md`: strings only, muted, and `aria-hidden`. Use `format`
   * first. Affixes are for units Intl cannot format ("/mo", "per seat").
   */
  prefix?: string
  /**
   * Hides the steppers, because a value that cannot be edited cannot be stepped.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  step?: number
  suffix?: string
  /**
   * `null` is the empty field.
   */
  value?: number | null
}

/** A field that holds, formats and steps a number. */
export default function NumberInput(given: NumberInputProps): JSX.Element {
  const props = mergeProps(
    { size: 'md', disabled: false, readOnly: false, invalid: false } as Defaults<
      NumberInputProps,
      'size' | 'disabled' | 'readOnly' | 'invalid'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const control = elementRef<HTMLElement>()
    const committed = createCell(
      props.value === undefined ? (props.defaultValue ?? null) : props.value,
    )
    const draft = createCell('')
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          defaultValue:
            (props.value === undefined ? props.defaultValue : props.value) === undefined
              ? undefined
              : (props.value === undefined ? props.defaultValue : props.value) === null
                ? ''
                : String(props.value === undefined ? props.defaultValue : props.value),
          min: props.min,
          max: props.max,
          step: props.step,
          formatOptions: props.format,
          disabled: props.disabled,
          readOnly: props.readOnly,
          invalid: props.invalid,
          required: props['aria-required'],
          allowMouseWheel: false,
          ids: props.id === undefined ? undefined : { input: props.id },
          onValueChange: (details) => {
            void (service.event.current().type === 'INPUT.CHANGE'
              ? (draft.value = details.value)
              : ['INPUT.BLUR', 'INPUT.ENTER', 'VALUE.SET', 'VALUE.CLEAR'].includes(
                  service.event.current().type,
                ) ||
                ((next) =>
                  next === committed.value || ((committed.value = next), props.onChange?.(next)))(
                  Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber,
                ))
          },
          onValueCommit: (details) => {
            void (Number.isNaN(details.valueAsNumber) && draft.value.trim() !== ''
              ? committed.value === null
                ? api.value.clearValue()
                : api.value.setValue(committed.value)
              : ((next) =>
                  next === committed.value || ((committed.value = next), props.onChange?.(next)))(
                  Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber,
                ))
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const effect1 = () => {
      void (
        props.value === undefined ||
        props.value === committed.value ||
        ((committed.value = props.value),
        props.value === null ? api.value.clearValue() : api.value.setValue(props.value))
      )
    }
    watchEffect(
      createMemo(() => [props.value, committed.value]),
      effect1,
      false,
    )
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'NumberInput',
        element: () => control.value,
        state: () => ({
          value: committed.value,
          disabled: props.disabled,
          invalid: props.invalid,
          readonly: props.readOnly,
        }),
        actions: {
          set: {
            argument: 'number',
            run: (value) =>
              (() => {
                if (props.readOnly) throw new Error('The field is read-only.')
                const next = Math.min(
                  Math.max(value, props.min ?? -Infinity),
                  props.max ?? Infinity,
                )
                api.value.setValue(next)
                ;((next) =>
                  next === committed.value || ((committed.value = next), props.onChange?.(next)))(
                  Number.isNaN(next) ? null : next,
                )
              })(),
          },
          clear: () =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              api.value.clearValue()
              ;((next) =>
                next === committed.value || ((committed.value = next), props.onChange?.(next)))(
                Number.isNaN(NaN) ? null : NaN,
              )
            })(),
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        {...mergeParts(api.value.getRootProps(), {
          class: styles.field,
          'data-size': props.size,
          'data-disabled': props.disabled ? '' : undefined,
          'data-invalid': props.invalid ? '' : undefined,
          'data-readonly': props.readOnly ? '' : undefined,
          'data-member': 'number-input',
          onmousedown: ($event: MouseEvent) =>
            !$event
              .composedPath()
              .some(
                (node) =>
                  'nodeName' in node &&
                  ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(String(node.nodeName)),
              ) && ($event.preventDefault(), api.value.focus()),
        })}
      >
        {props.prefix !== undefined ? (
          <span class={styles.affix} aria-hidden="true">
            {props.prefix}
          </span>
        ) : null}
        {/* field */}
        <input
          {...mergeParts(api.value.getInputProps(), {
            class: styles.input,
            name: undefined,
            placeholder: props.placeholder,
            role: undefined,
            'aria-valuemin': undefined,
            'aria-valuemax': undefined,
            'aria-valuenow': undefined,
            'aria-valuetext': undefined,
            'aria-label': props['aria-label'],
            'aria-labelledby': props['aria-labelledby'],
            'aria-describedby': props['aria-describedby'],
            'aria-required': props['aria-required'],
            onblur: ($event: FocusEvent) => props.onBlur?.($event),
            onfocus: ($event: FocusEvent) => props.onFocus?.($event),
          })}
          ref={control.attach}
        />
        {props.suffix !== undefined ? (
          <span class={styles.affix} aria-hidden="true">
            {props.suffix}
          </span>
        ) : null}
        {!props.readOnly ? (
          <div class={styles.steppers}>
            {/* stepper */}
            <button
              {...mergeParts(api.value.getDecrementTriggerProps(), { class: styles.stepper })}
            >
              <Icon name="down" size={props.size} />
            </button>
            {/* stepper */}
            <button
              {...mergeParts(api.value.getIncrementTriggerProps(), { class: styles.stepper })}
            >
              <Icon name="up" size={props.size} />
            </button>
          </div>
        ) : null}
        {props.name !== undefined ? (
          <input
            type="hidden"
            name={props.name}
            value={committed.value ?? ''}
            disabled={props.disabled || undefined}
          />
        ) : null}
      </div>
    )
  })
}
